    /// An inference variable for each of `ts`, solved to it: what a
    /// turbofish notes, settled with the definition.
    pub fn fresh_for(s: &'static St, ts: Tys) -> &'static FreshMetas {
        if null_p(ts) {
            fresh_metas(nil::<i64>(), s)
        } else {
            let tagcase_ = walk(s, car(ts));
            match *tagcase_ {
                Ty::TyMeta(k) => {
                    let tagcase_ = fresh_for(s, cdr(ts));
                    match *tagcase_ {
                        FreshMetas::FreshMetas(ks, s) => {
                            fresh_metas(kayak_rt::heap_cons(k, ks), s)
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    let tagcase_ = fresh(s);
                    match *tagcase_ {
                        Res::Res(m, es, s) => {
                            let tagcase_ = m;
                            match *tagcase_ {
                                Ty::TyMeta(k) => {
                                    let tagcase_ = fresh_for(solve(s, k, other), cdr(ts));
                                    match *tagcase_ {
                                        FreshMetas::FreshMetas(ks, s) => {
                                            fresh_metas(kayak_rt::heap_cons(k, ks), s)
                                        }
                                    }
                                }
                                _ => {
                                    let other2 = tagcase_;
                                    fresh_metas(nil::<i64>(), s)
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /// That the datum at `file`, `pos` has `what`, types `ts`, settled with
    /// the definition: `what T ...`.
    pub fn note_types(s: &'static St, file: Str, pos: i64, what: Str, ts: Tys) -> &'static St {
        let tagcase_ = fresh_for(s, ts);
        match *tagcase_ {
            FreshMetas::FreshMetas(ks, s) => {
                note_fact(s, file, pos, string_append(str_lit("%metas "), string_append(what, string_append(str_lit(" "), words_of(map(&meta_name, ks))))))
            }
        }
    }

    /// That the datum at `file`, `pos` is written at types `ts`.
    pub fn note_turbofish(s: &'static St, file: Str, pos: i64, ts: Tys) -> &'static St {
        if null_p(ts) {
            s
        } else {
            note_types(s, file, pos, str_lit("turbofish"), ts)
        }
    }

    /// The inference variables a poly's instantiation made, `from` to `to`,
    /// its type binders': not its regions'.
    pub fn binder_metas(from: i64, to: i64, regions: List<i64>) -> List<i64> {
        if not(i64_lt(from, to)) {
            nil::<i64>()
        } else {
            let rest = binder_metas(i64_plus(from, 1i64), to, regions);
            if any_p(lambda1s(move |r: i64| {
                i64_eq(r, from)
            }), regions) {
                rest
            } else {
                kayak_rt::heap_cons(from, rest)
            }
        }
    }

    pub fn member_type(mut l: Str, mut ls: Strings, mut ts: Tys) -> &'static Ty {
        loop {
            if string_eq_p(car(ls), l) {
                return car(ts);
            } else {
                (ls, ts) = (cdr(ls), cdr(ts));
                continue;
            }
        }
    }

